insert into public.posts (slug, title, excerpt, content, cover_image, tags, status, published_at, seo_title, seo_description) values
  ('building-an-immersive-portfolio', 'Building an immersive portfolio without killing performance', 'How I kept Lighthouse at 95+ while shipping React Three Fiber scenes, smooth scroll and an AI assistant.', '## The constraint
